<template><section class="workbench"><div class="head"><div><span class="eyebrow">PHM WORKBENCH / {{route.name||'MODULE'}}</span><h2>{{title}}</h2><p>{{description}}</p></div><el-tag type="warning">算法服务未启用</el-tag></div><el-alert title="本页面支持数据源配置和任务提交。算法服务尚未启用时，任务会保存为待执行配置，不会伪造分析结果。" type="info" :closable="false" show-icon/><div class="grid"><el-card shadow="never"><template #header><b>数据源</b></template><el-form label-position="top"><el-form-item label="数据来源"><el-radio-group v-model="form.source"><el-radio-button label="dataset">仿真数据集</el-radio-button><el-radio-button label="upload">上传文件</el-radio-button><el-radio-button label="history">历史记录</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="form.source==='dataset'" label="场景"><el-select v-model="form.category" placeholder="选择仿真场景" style="width:100%"><el-option v-for="x in categories" :key="x.key" :label="x.name" :value="x.key"/></el-select></el-form-item><el-form-item v-if="form.source==='upload'" label="CSV / Excel / MAT 文件"><el-upload drag :auto-upload="false" :limit="1" accept=".csv,.xlsx,.xls,.mat" :on-change="onFile"><el-icon><UploadFilled/></el-icon><div>拖拽文件到此处，或点击选择</div><small>文件仅用于创建分析任务</small></el-upload></el-form-item><el-form-item label="任务备注"><el-input v-model="form.note" type="textarea" :rows="3" placeholder="记录本次分析目的或参数"/></el-form-item><el-button type="primary" :loading="submitting" @click="submit">提交分析任务</el-button></el-form></el-card><el-card shadow="never"><template #header><b>任务状态</b></template><el-empty v-if="!lastTask" description="尚未提交任务"/><div v-else class="task"><el-tag type="warning">{{lastTask.status}}</el-tag><h3>{{lastTask.name}}</h3><p>数据源：{{lastTask.source}}</p><p>创建时间：{{lastTask.time}}</p><p>{{lastTask.note||'未填写备注'}}</p><el-divider/><b>下一步</b><p class="muted">连接算法服务后，任务将在后台执行并在此展示结果。</p></div></el-card></div><el-card shadow="never" class="features"><template #header><b>模块能力</b></template><el-tag v-for="item in features" :key="item" effect="plain">{{item}}</el-tag></el-card></section></template>
<script setup>import{ref,computed,onMounted}from'vue';import{useRoute}from'vue-router';import{UploadFilled}from'@element-plus/icons-vue';import{ElMessage}from'element-plus';const route=useRoute(),title=computed(()=>route.meta.title||'PHM 功能模块'),description=computed(()=>route.meta.description||'配置数据源并提交分析任务。'),features=computed(()=>route.meta.features||[]),categories=ref([]),file=ref(null),submitting=ref(false),lastTask=ref(null),form=ref({source:'dataset',category:'',note:''});onMounted(async()=>{try{const r=await fetch('/api/v1/simulation-dataset/catalog/');categories.value=(await r.json()).categories||[];if(categories.value.length)form.value.category=categories.value[0].key}catch{}});const onFile=f=>{file.value=f.raw};const submit=async()=>{if(form.value.source==='upload'&&!file.value){ElMessage.warning('请先选择文件');return}submitting.value=true;await new Promise(r=>setTimeout(r,350));lastTask.value={name:title.value,source:form.value.source==='upload'?(file.value?.name||'上传文件'):(form.value.source==='dataset'?(categories.value.find(x=>x.key===form.value.category)?.name||'仿真数据集'):'历史记录'),note:form.value.note,status:'待执行',time:new Date().toLocaleString('zh-CN',{hour12:false})};localStorage.setItem(`phm-task-${route.path}`,JSON.stringify(lastTask.value));submitting.value=false;ElMessage.success('任务配置已保存')};onMounted(()=>{const x=localStorage.getItem(`phm-task-${route.path}`);if(x)lastTask.value=JSON.parse(x)});</script>
<style scoped>.workbench{background:#fff;border:1px solid #e6ebf2;border-radius:12px;padding:25px;box-shadow:0 5px 20px #18385b0a}.head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.eyebrow{font-size:11px;color:#287de6;font-weight:700;letter-spacing:1px}.head h2{margin:7px 0}.head p{margin:0;color:#79899e}.grid{display:grid;grid-template-columns:1.2fr 1fr;gap:18px;margin-top:18px}.el-card{border-radius:10px}.task h3{margin:18px 0 10px}.task p{color:#65768c;font-size:13px}.muted{color:#8997a9!important}.features{margin-top:18px}.features .el-tag{margin-right:9px;margin-bottom:7px}@media(max-width:900px){.grid{grid-template-columns:1fr}}</style>
